// Cards from the design slides (Google Slides "カード案"), card text kept as written (xiコロ -> サイコロ).
//
// Flags used here:
//   wip        : text is shown, effect not implemented yet (needs a rule/mechanic that doesn't exist, or ambiguous)
//   unverified : a field the slides did not state (machine / tendency / tags) was filled in by a guess — please correct it
//   token      : generated by other cards, not selectable in the deck builder
//
// Tags (chara): used by conditions like "場にWACCAキャラ" — only filled in where the slides imply them.

const S = 'サイコロ';
const art = (n) => `assets/art/${n}.jpg`;
const ARCADE = ['maimai', 'ongeki', 'chunithm', 'wacca', 'gfdm', 'ddr', 'beatmania', 'sdvx'];   // 課金 works on these machines' songs
const T = (c) => ({ type: 'chara', ...c });
const K = (c) => ({ type: 'skill', source: '', attr: 'half', footer: 'スキル', ...c });
const play = (...ops) => [{ when: 'play', ops }];
const chartOf = (c) => ({ type: 'chart', footer: [].concat(c.tendency || 'NONE').join(' / '), ...c });

